var DATA = {"method": "Reciprocal rank fusion (k=60)", "sources": "Backend A, Backend B, Backend C", "lists": "d1|d2|d3;d2|d4|d1;d3|d1|d5"};
console.log("Fusion method: " + DATA.method + " over " + DATA.sources + ".");
var lists = DATA.lists.split(";").map(function (l) { return l.split("|").map(function (s) { return s.trim(); }); });
// reciprocal rank fusion
var scores = {};
lists.forEach(function (list) {
  list.forEach(function (doc, rank) {
    scores[doc] = (scores[doc] || 0) + 1 / (60 + rank + 1);
  });
});
var fused = Object.keys(scores).sort(function (a, b) { return scores[b] - scores[a]; });
console.log("Fused ranking:");
fused.forEach(function (d, i) { console.log("  " + (i + 1) + ". " + d + " (rrf=" + scores[d].toFixed(4) + ")"); });
console.log("RESULT: " + fused.length + " documents fused from " + lists.length + " source rankings.");

